-- Customer codes are generated by a counter scoped to each landing link.
-- The old schema used global UNIQUE(customer_code), which incorrectly caused
-- two different links using the same prefix (for example F-HT-1027/-1) to clash.
-- Rebuild both session and prefetch tables with composite per-link uniqueness.

CREATE TABLE customer_code_sessions_new (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  slug TEXT NOT NULL,
  session_token TEXT NOT NULL,
  customer_code TEXT NOT NULL,
  source TEXT NOT NULL DEFAULT 'direct',
  agent TEXT NOT NULL DEFAULT 'unknown',
  first_seen TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')),
  last_seen TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')),
  page_views INTEGER NOT NULL DEFAULT 0,
  whatsapp_clicks INTEGER NOT NULL DEFAULT 0,
  UNIQUE(slug, session_token),
  UNIQUE(slug, customer_code)
);

INSERT INTO customer_code_sessions_new (
  id, slug, session_token, customer_code, source, agent,
  first_seen, last_seen, page_views, whatsapp_clicks
)
SELECT
  id, slug, session_token, customer_code, source, agent,
  first_seen, last_seen, page_views, whatsapp_clicks
FROM customer_code_sessions;

DROP TABLE customer_code_sessions;
ALTER TABLE customer_code_sessions_new RENAME TO customer_code_sessions;

CREATE TABLE wa_prefetch_queue_new (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  slug TEXT NOT NULL,
  customer_code TEXT NOT NULL,
  wa_number_id INTEGER NOT NULL,
  cycle INTEGER NOT NULL,
  status TEXT NOT NULL DEFAULT 'ready',
  claimed_session_token TEXT,
  created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')),
  claimed_at TEXT,
  UNIQUE(slug, customer_code)
);

INSERT INTO wa_prefetch_queue_new (
  id, slug, customer_code, wa_number_id, cycle, status,
  claimed_session_token, created_at, claimed_at
)
SELECT
  id, slug, customer_code, wa_number_id, cycle, status,
  claimed_session_token, created_at, claimed_at
FROM wa_prefetch_queue;

DROP TABLE wa_prefetch_queue;
ALTER TABLE wa_prefetch_queue_new RENAME TO wa_prefetch_queue;

CREATE INDEX IF NOT EXISTS idx_customer_sessions_slug_token
  ON customer_code_sessions(slug, session_token);
CREATE INDEX IF NOT EXISTS idx_wa_queue_slug_status_id
  ON wa_prefetch_queue(slug, status, id);
